fn clamp(value: i32, low: i32, high: i32) -> i32 {
    if value < low {
        low
    } else if value > high {
        high
    } else {
        value
    }
}

fn main() {
    println!("{} {} {}", clamp(-5, 0, 10), clamp(7, 0, 10), clamp(42, 0, 10));
}

